fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // For each element in x, produce true if it is DateTime64::Nat, else false.
    x.iter()
        .map(|dt| match dt {
            DateTime64::Nat => true,
            DateTime64::Valid(_) => false,
        })
        .collect()
}